Design:
{
 "context": "payments",
 "base_package": "com.bank.payments",
 "entities": [
  {
   "name": "Order",
   "table": "orders",
   "legacy_table": "ORDENES",
   "key": [
    "orderNumber",
    "company"
   ],
   "fields": [
    {
     "name": "orderNumber",
     "type": "integer(32,signed)",
     "column": "order_number",
     "legacy": "ORD_NUMERO"
    },
    {
     "name": "company",
     "type": "integer(32,signed)",
     "column": "company_id",
     "legacy": "ORD_EMPRESA"
    },
    {
     "name": "status",
     "type": "text(fixed,1,iso8859-1)",
     "column": "status",
     "legacy": "ORD_ESTADO"
    },
    {
     "name": "orderValue",
     "type": "decimal(11,2,signed)",
     "column": "order_value",
     "legacy": "ORD_VALOR"
    },
    {
     "name": "movementNumber",
     "type": "integer(64,signed)",
     "column": "movement_number",
     "legacy": "ORD_MOVIM"
    },
    {
     "name": "commission",
     "type": "decimal(5,2,signed)",
     "column": "commission",
     "legacy": "ORD_COMIS"
    }
   ]
  },
  {
   "name": "Account",
   "table": "accounts",
   "legacy_table": "CUENTAS",
   "key": [
    "accountNumber"
   ],
   "fields": [
    {
     "name": "accountNumber",
     "type": "integer(64,signed)",
     "column": "account_number",
     "legacy": "CTA_NUMERO"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": "account_type",
     "legacy": "CTA_TIPO"
    },
    {
     "name": "balance",
     "type": "decimal(13,2,signed)",
     "column": "balance",
     "legacy": "CTA_SALDO"
    },
    {
     "name": "status",
     "type": "text(fixed,1,iso8859-1)",
     "column": "status",
     "legacy": "CTA_ESTADO"
    }
   ]
  }
 ],
 "ports": [
  {
   "name": "OrderRepository",
   "entity": "Order",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByKey",
     "description": "Reads an order by order number and company (READ of ORDENES for update).",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_NUMERO"
      },
      {
       "name": "company",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_EMPRESA"
      }
     ],
     "returns": "Order",
     "legacy_output": null
    },
    {
     "name": "markPaid",
     "description": "Sets the order to paid (status G) and stores the movement number and the commission (REWRITE of ORDENES).",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_NUMERO"
      },
      {
       "name": "company",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_EMPRESA"
      },
      {
       "name": "movementNumber",
       "type": "integer(64,signed)",
       "column": null,
       "legacy": "ORD_MOVIM"
      },
      {
       "name": "commission",
       "type": "decimal(5,2,signed)",
       "column": null,
       "legacy": "ORD_COMIS"
      }
     ],
     "returns": null,
     "legacy_output": null
    }
   ]
  },
  {
   "name": "AccountRepository",
   "entity": "Account",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByNumber",
     "description": "Reads an account by number (READ of CUENTAS for update).",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "integer(64,signed)",
       "column": null,
       "legacy": "CTA_NUMERO"
      }
     ],
     "returns": "Account",
     "legacy_output": null
    },
    {
     "name": "updateBalance",
     "description": "Stores the new balance of the account (REWRITE of CUENTAS).",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "integer(64,signed)",
       "column": null,
       "legacy": "CTA_NUMERO"
      },
      {
       "name": "balance",
       "type": "decimal(13,2,signed)",
       "column": null,
       "legacy": "CTA_SALDO"
      }
     ],
     "returns": null,
     "legacy_output": null
    }
   ]
  },
  {
   "name": "MovementGateway",
   "entity": null,
   "legacy_program": "PAGOMOV",
   "methods": [
    {
     "name": "registerMovement",
     "description": "Registers the movement of the payment and returns its number (LINK PAGOMOV).",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "MOV_ORDEN"
      }
     ],
     "returns": "long",
     "legacy_output": "MOV_NUMERO"
    }
   ]
  }
 ],
 "use_cases": [
  {
   "name": "MenuOptionRouting",
   "description": "Routes the option chosen on the payments main menu: 1 opens the payment of orders, 9 ends the session, anything else is rejected as an invalid option.",
   "rules": [
    "RULE-006"
   ],
   "inputs": [
    {
     "name": "option",
     "type": "text(fixed,1,iso8859-1)",
     "column": null,
     "legacy": "OPCIONI"
    }
   ],
   "outputs": [
    {
     "name": "destination",
     "type": "text(var,20,iso8859-1)",
     "column": null,
     "legacy": "OPCIONO"
    },
    {
     "name": "message",
     "type": "text(var,78,iso8859-1)",
     "column": null,
     "legacy": "MENSAJEO"
    }
   ],
   "errors": [
    {
     "code": "INVALID_OPTION",
     "legacy_code": "OPCION NO VALIDA",
     "message": "OPCION NO VALIDA"
    }
   ],
   "ports": [],
   "http_method": "POST",
   "path": "/menu/options",
   "legacy_program": "PAGOMNU",
   "unit_of_work": null,
   "legacy_message": "MENSAJEO"
  },
  {
   "name": "PayOrder",
   "description": "Pays a pending order (PAGOORD). Validates the entry, reads the order, checks the amount, calculates the commission, debits the customer account (logic of PAGODEB: the account must exist, its type must match, it must be active and the balance must cover the total; then the balance is reduced), registers the movement and marks the order as paid, all in one transaction.",
   "rules": [
    "RULE-001",
    "RULE-002",
    "RULE-003",
    "RULE-004",
    "RULE-005",
    "RULE-007",
    "RULE-008",
    "RULE-009",
    "RULE-010",
    "RULE-011",
    "RULE-012",
    "RULE-013",
    "RULE-014",
    "RULE-015"
   ],
   "inputs": [
    {
     "name": "orderNumber",
     "type": "text(fixed,7,iso8859-1)",
     "column": null,
     "legacy": "ORDEN"
    },
    {
     "name": "company",
     "type": "text(fixed,5,iso8859-1)",
     "column": null,
     "legacy": "EMPRESA"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "TIPCTA"
    },
    {
     "name": "account",
     "type": "text(fixed,10,iso8859-1)",
     "column": null,
     "legacy": "CUENTA"
    },
    {
     "name": "amount",
     "type": "decimal(11,2,signed)",
     "column": null,
     "legacy": "VALOR"
    },
    {
     "name": "channel",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "CANAL"
    },
    {
     "name": "approvalKey",
     "type": "text(fixed,6,iso8859-1)",
     "column": null,
     "legacy": "CLAVE"
    }
   ],
   "outputs": [
    {
     "name": "paidOrder",
     "type": "text(fixed,7,iso8859-1)",
     "column": null,
     "legacy": "RORDEN"
    },
    {
     "name": "commission",
     "type": "decimal(5,2,signed)",
     "column": null,
     "legacy": "RCOMIS"
    },
    {
     "name": "movementNumber",
     "type": "integer(64,signed)",
     "column": null,
     "legacy": "RMOVIM"
    },
    {
     "name": "resultMessage",
     "type": "text(var,40,iso8859-1)",
     "column": null,
     "legacy": "RMENS"
    }
   ],
   "errors": [
    {
     "code": "INVALID_ORDER_NUMBER",
     "legacy_code": "NUMERO DE ORDEN INVALIDO",
     "message": "NUMERO DE ORDEN INVALIDO"
    },
    {
     "code": "ACCOUNT_TYPE_NOT_ALLOWED",
     "legacy_code": "TIPO DE CUENTA NO PERMITIDO",
     "message": "TIPO DE CUENTA NO PERMITIDO"
    },
    {
     "code": "CHANNEL_NOT_ALLOWED",
     "legacy_code": "CANAL NO PERMITIDO",
     "message": "CANAL NO PERMITIDO"
    },
    {
     "code": "APPROVAL_KEY_REQUIRED",
     "legacy_code": "CLAVE DE APROBACION REQUERIDA",
     "message": "CLAVE DE APROBACION REQUERIDA"
    },
    {
     "code": "ORDER_NOT_FOUND",
     "legacy_code": "ORDEN NO EXISTE",
     "message": "ORDEN NO EXISTE"
    },
    {
     "code": "ORDER_NOT_PENDING",
     "legacy_code": "ORDEN NO ESTA PENDIENTE",
     "message": "ORDEN NO ESTA PENDIENTE"
    },
    {
     "code": "AMOUNT_MISMATCH",
     "legacy_code": "VALOR NO COINCIDE CON LA ORDEN",
     "message": "VALOR NO COINCIDE CON LA ORDEN"
    },
    {
     "code": "PAYMENT_ACCOUNT_INACTIVE",
     "legacy_code": "CUENTA INACTIVA",
     "message": "CUENTA INACTIVA"
    },
    {
     "code": "PAYMENT_INSUFFICIENT_FUNDS",
     "legacy_code": "SALDO INSUFICIENTE",
     "message": "SALDO INSUFICIENTE"
    },
    {
     "code": "PAYMENT_INVALID_ACCOUNT",
     "legacy_code": "CUENTA NO VALIDA",
     "message": "CUENTA NO VALIDA"
    }
   ],
   "ports": [
    "OrderRepository",
    "AccountRepository",
    "MovementGateway"
   ],
   "http_method": "POST",
   "path": "/payments/orders/pay",
   "legacy_program": "PAGOORD",
   "unit_of_work": {
    "begins_at": 37,
    "commits_at": 172,
    "savepoints": [],
    "rollbacks": []
   },
   "legacy_message": "MENSAJE"
  }
 ],
 "decisions": [
  {
   "title": "Data of the VSAM files moves to relational tables",
   "context": "ORDENES and CUENTAS are VSAM KSDS files read and rewritten with CICS commands. PAGOMOV is not in the inputs.",
   "decision": "ORDENES and CUENTAS become the tables orders and accounts of the target database (data_strategy migration). The legacy precision is kept: S9(9)V99 becomes decimal(11,2), S9(11)V99 becomes decimal(13,2), S9(3)V99 becomes decimal(5,2). Status values P (pending) and G (paid) of orders and A/I of accounts are kept as they are.",
   "consequences": "A data migration is needed before go-live. Reads for update become row locks inside the transaction."
  },
  {
   "title": "The LINK to PAGODEB is absorbed into the PayOrder use case",
   "context": "PAGOORD debits the account with EXEC CICS LINK to PAGODEB (rules 001 to 005). PAGODEB is only called from PAGOORD, passes data through a commarea and has no entry point of its own in the traces.",
   "decision": "The debit logic is implemented inside PayOrder using AccountRepository, in the legacy order: account not found, type mismatch, inactive, balance lower than the total, then the balance is reduced. The PAGODEB response codes are mapped as in PAGOORD: 10 gives CUENTA INACTIVA, 20 gives SALDO INSUFICIENTE, and 30 and 40 give CUENTA NO VALIDA. The debit is not exposed as a separate endpoint.",
   "consequences": "The debit and the order update commit or roll back together, which is stricter than the legacy (two programs under one syncpoint). The PAGODEB commarea disappears."
  },
  {
   "title": "Transaction boundary of the payment",
   "context": "PAGOORD works inside one logical unit of work, which ends with the SYNCPOINT after the order is rewritten. It has no savepoints and no explicit rollback points. Rejections happen before anything is written.",
   "decision": "PayOrder is transactional from begin (line 37) to commit (line 172). Business rejections raise the error before any write, so no rollback entry is needed. Any technical exception rolls back the whole unit.",
   "consequences": "A rejection never leaves partial changes: balance and order stay untouched, as the traces show. No UnitOfWork port is needed because there are no savepoints."
  },
  {
   "title": "PAGOMOV is an external program behind a port",
   "context": "PAGOMOV is not in the inputs and is stubbed in the traces. It receives the order number (MOV_ORDEN) and returns the movement number (MOV_NUMERO).",
   "decision": "It is accessed through the MovementGateway port, with a generated adapter for PAGOMOV. The legacy ignores the status of the LINK, and the design keeps that behaviour.",
   "consequences": "The real PAGOMOV must be provided or migrated in a later step. Tests use the stub of the traces."
  },
  {
   "title": "Screens and pseudo-conversation are replaced by REST",
   "context": "The legacy uses BMS maps (PAGOMEN, PAGOORD, PAGORES), the PGMN and PGOR transactions, a 13-byte commarea, PF keys and XCTL between programs.",
   "decision": "Each use case is a REST endpoint. The commarea, the map handling, PF3 and the key validation (TECLA NO VALIDA) are not translated. The menu routes the option and returns the destination. Rejection messages go in the error response with the same text as the legacy message. CA-ULTIMA-ORDEN lived only in the pseudo-conversational session and is not persisted.",
   "consequences": "Navigation is the responsibility of the client. The text of the messages is kept so the golden master can compare it."
  },
  {
   "title": "The entered amount arrives as a decimal",
   "context": "The map field VALOR is PIC 9(9)V99 and the legacy computes NUMVAL(VALORI)/100 before comparing it with ORD-VALOR. The traces enter 1500.00 for an order of 1500.00 and the payment succeeds.",
   "decision": "The amount is a decimal(11,2) input. The comparison with the order value (RULE-012) is made exactly, with no rounding. The scaling of the screen text is the job of the entry adapter.",
   "consequences": "The business comparison is the same as the traces show. The scaling of the raw screen input has to be confirmed by a reviewer."
  },
  {
   "title": "Text inputs keep their validation",
   "context": "Order number, company and account arrive as text, and RULE-007 requires a numeric and non-zero order number.",
   "decision": "PayOrder receives them as text(fixed) and validates them as in the legacy before converting them to numbers for the repositories. Validations run in the legacy order: order number, account type, channel, approval key. Only the first error is reported.",
   "consequences": "An order number such as 12A4567 is rejected with INVALID_ORDER_NUMBER, never with a type error."
  }
 ],
 "masks": [],
 "infrastructure": [],
 "data_strategy": "migration"
}

Use case: PayOrder

Rules:
[
 {
  "id": "RULE-001",
  "name": "Debit rejected when account does not exist",
  "category": "validation",
  "priority": "P0",
  "statement": "A debit against an account number that is not on the CUENTAS file is rejected with response code '30' and the balance is not changed.",
  "condition": "READ of CUENTAS by DEB-CUENTA returns NOTFND",
  "action": "Set DEB-RESP = '30'; no debit is made.",
  "inputs": [
   {
    "name": "DEB-CUENTA",
    "type": "decimal(10,0,unsigned)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "DEB-RESP",
    "type": "text(fixed,2,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Account not found\n Given no account 9999999999 exists in CUENTAS\n When a debit of 100.00 is requested for account 9999999999\n Then DEB-RESP is '30'\n And no balance is changed"
  ],
  "sources": [
   {
    "file": "cbl/PAGODEB.cbl",
    "line_start": 18,
    "line_end": 23
   }
  ]
 },
 {
  "id": "RULE-002",
  "name": "Debit rejected when account type differs from requested type",
  "category": "validation",
  "priority": "P0",
  "statement": "When the account type stored on the account (CTA-TIPO) is not equal to the type requested in the debit (DEB-TIPO), DEB-RESP is set to '40'.",
  "condition": "Account found AND CTA-TIPO <> DEB-TIPO",
  "action": "Set DEB-RESP = '40'; no debit is made.",
  "inputs": [
   {
    "name": "CTA-TIPO",
    "type": "text(fixed,3,ebcdic)",
    "description": ""
   },
   {
    "name": "DEB-TIPO",
    "type": "text(fixed,3,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "DEB-RESP",
    "type": "text(fixed,2,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Type mismatch\n Given account 1234567890 exists with CTA-TIPO 'AHO'\n When a debit of 50.00 is requested with DEB-TIPO 'COR'\n Then DEB-RESP is '40'\n And the balance is unchanged"
  ],
  "sources": [
   {
    "file": "cbl/PAGODEB.cbl",
    "line_start": 24,
    "line_end": 25
   }
  ]
 },
 {
  "id": "RULE-003",
  "name": "Debit rejected when account is not active",
  "category": "validation",
  "priority": "P0",
  "statement": "When the account is not active (NOT CTA-ACTIVA), DEB-RESP is set to '10'.",
  "condition": "Account found AND CTA-TIPO = DEB-TIPO AND NOT CTA-ACTIVA",
  "action": "Set DEB-RESP = '10'; no debit is made.",
  "inputs": [
   {
    "name": "CTA-ESTADO",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "DEB-RESP",
    "type": "text(fixed,2,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Inactive account\n Given account 1234567890 exists, the type matches, and the account is not active\n When a debit of 50.00 is requested\n Then DEB-RESP is '10'\n And the balance is unchanged"
  ],
  "sources": [
   {
    "file": "cbl/PAGODEB.cbl",
    "line_start": 26,
    "line_end": 27
   }
  ]
 },
 {
  "id": "RULE-004",
  "name": "Debit rejected for insufficient funds",
  "category": "validation",
  "priority": "P0",
  "statement": "When CTA-SALDO is strictly less than DEB-MONTO, the debit is rejected by setting DEB-RESP to '20'. A debit equal to the balance is not rejected by this check.",
  "condition": "Account found, type matches, account active AND CTA-SALDO < DEB-MONTO",
  "action": "Set DEB-RESP = '20'; no debit is made.",
  "inputs": [
   {
    "name": "CTA-SALDO",
    "type": "decimal(13,2,signed)",
    "description": ""
   },
   {
    "name": "DEB-MONTO",
    "type": "decimal(13,2,signed)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "DEB-RESP",
    "type": "text(fixed,2,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Insufficient balance\n Given an active account with CTA-SALDO 100.00 and a matching type\n When a debit of 100.01 is requested\n Then DEB-RESP is '20'\n And the balance stays 100.00",
   "Scenario: Balance equal to amount is allowed\n Given an active account with CTA-SALDO 100.00 and a matching type\n When a debit of 100.00 is requested\n Then the debit proceeds"
  ],
  "sources": [
   {
    "file": "cbl/PAGODEB.cbl",
    "line_start": 28,
    "line_end": 29
   }
  ]
 },
 {
  "id": "RULE-005",
  "name": "Successful debit reduces balance",
  "category": "calculation",
  "priority": "P0",
  "statement": "When none of the preceding WHEN branches of the evaluation apply (WHEN OTHER), the debit amount DEB-MONTO is subtracted from CTA-SALDO, the CUENTAS record is rewritten from CTA-REGISTRO, and DEB-RESP is set to '00'.",
  "condition": "None of the rejection conditions ('30','40','10','20') apply",
  "action": "CTA-SALDO = CTA-SALDO - DEB-MONTO; REWRITE the CUENTAS record; DEB-RESP = '00'.",
  "inputs": [
   {
    "name": "CTA-SALDO",
    "type": "decimal(13,2,signed)",
    "description": ""
   },
   {
    "name": "DEB-MONTO",
    "type": "decimal(13,2,signed)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "CTA-SALDO",
    "type": "decimal(13,2,signed)",
    "description": ""
   },
   {
    "name": "DEB-RESP",
    "type": "text(fixed,2,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Successful debit\n Given an active account with CTA-SALDO 500.00 and a matching type\n When a debit of 120.50 is requested\n Then CTA-SALDO becomes 379.50\n And DEB-RESP is '00'"
  ],
  "sources": [
   {
    "file": "cbl/PAGODEB.cbl",
    "line_start": 30,
    "line_end": 31
   },
   {
    "file": "cbl/PAGODEB.cbl",
    "line_start": 35,
    "line_end": 39
   }
  ]
 },
 {
  "id": "RULE-007",
  "name": "Order number must be numeric and non-zero",
  "category": "validation",
  "priority": "P1",
  "statement": "When the order number ORDENI is not numeric or equals zeros, the message 'NUMERO DE ORDEN INVALIDO' is set in WS-MENSAJE and the HAY-ERROR flag is set.",
  "condition": "ORDENI NOT NUMERIC OR ORDENI = ZEROS",
  "action": "Set message 'NUMERO DE ORDEN INVALIDO' and flag the request as in error. No order is read and no debit is made.",
  "inputs": [
   {
    "name": "ORDENI",
    "type": "text(fixed,7,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "WS-MENSAJE",
    "type": "text(fixed,78,ebcdic)",
    "description": ""
   },
   {
    "name": "WS-ERROR",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Order number is zero\n Given the order number entered is 0000000\n When the user presses ENTER\n Then the message 'NUMERO DE ORDEN INVALIDO' is shown and the payment is not processed",
   "Scenario: Order number contains letters\n Given the order number entered is 12A4567\n When the user presses ENTER\n Then the message 'NUMERO DE ORDEN INVALIDO' is shown"
  ],
  "sources": [
   {
    "file": "cbl/PAGOORD.cbl",
    "line_start": 83,
    "line_end": 85
   }
  ]
 },
 {
  "id": "RULE-008",
  "name": "Allowed account types for order payment",
  "category": "validation",
  "priority": "P0",
  "statement": "Only account types CTE, AHO and VIR may be used to pay an order. Any other type is rejected with 'TIPO DE CUENTA NO PERMITIDO'.",
  "condition": "TIPCTAI NOT IN ('CTE','AHO','VIR')",
  "action": "Set message 'TIPO DE CUENTA NO PERMITIDO' and flag the request as in error.",
  "inputs": [
   {
    "name": "TIPCTAI",
    "type": "text(fixed,3,ebcdic)",
    "description": ""
   }
